// Parse incoming TinyGS packet
const raw = msg.payload;

// Normalize to standard format
const normalized = {
    source: 'tinygs',
    timestamp: new Date().toISOString(),
    satellite: raw.satellite || raw.norad_id || 'Unknown',
    rssi: parseFloat(raw.rssi) || null,
    snr: parseFloat(raw.snr) || null,
    frequency: parseInt(raw.frequency) || null,
    station: raw.station || null,
    latitude: parseFloat(raw.latitude) || null,
    longitude: parseFloat(raw.longitude) || null,
    altitude: parseFloat(raw.altitude) || null,
    parsed: raw.parsed || null,
    raw: raw
};

msg.payload = normalized;
msg.topic = 'satellite/data';

// Add metadata
msg.satellite = normalized.satellite;
msg.source = 'tinygs';

return msg;

// Parse SatNOGS observations
const observations = msg.payload;

if (!Array.isArray(observations) || observations.length === 0) {
    return null;
}

// Process latest observation
const latest = observations[0];

const normalized = {
    source: 'satnogs',
    timestamp: latest.end || new Date().toISOString(),
    satellite: latest.norad_cat_id,
    observationId: latest.id,
    transmitter: latest.transmitter,
    mode: latest.mode,
    frequency: parseInt(latest.frequency) || null,
    waterfall: latest.waterfall || null,
    vetted_status: latest.vetted_status || 'unknown',
    station: latest.ground_station || null,
    raw: latest
};

msg.payload = normalized;
msg.topic = 'satellite/data';
msg.satellite = normalized.satellite;
msg.source = 'satnogs';

return msg;

// Aggregate data from multiple sources
const data = msg.payload;

// Store in flow context (last 100 packets)
let history = flow.get('packet_history') || [];
history.unshift(data);
if (history.length > 100) {
    history = history.slice(0, 100);
}
flow.set('packet_history', history);

// Calculate statistics
const stats = {
    totalPackets: history.length,
    uniqueSatellites: [...new Set(history.map(d => d.satellite))].length,
    avgRSSI: history
        .filter(d => d.rssi)
        .reduce((sum, d, i, arr) => sum + d.rssi / arr.length, 0)
        .toFixed(1),
    avgSNR: history
        .filter(d => d.snr)
        .reduce((sum, d, i, arr) => sum + d.snr / arr.length, 0)
        .toFixed(1),
    sourceBreakdown: history.reduce((acc, d) => {
        acc[d.source] = (acc[d.source] || 0) + 1;
        return acc;
    }, {})
};

flow.set('statistics', stats);

// Pass data forward
msg.payload = data;
msg.stats = stats;

return msg;

const data = msg.payload;
const alerts = [];

// Check RSSI threshold
if (data.rssi && data.rssi < -120) {
    alerts.push({
        type: 'warning',
        severity: 'medium',
        message: `Weak signal from ${data.satellite}: RSSI ${data.rssi} dBm`,
        timestamp: new Date().toISOString(),
        data: data
    });
}

// Check SNR threshold
if (data.snr && data.snr < -10) {
    alerts.push({
        type: 'warning',
        severity: 'medium',
        message: `Low SNR from ${data.satellite}: ${data.snr} dB`,
        timestamp: new Date().toISOString(),
        data: data
    });
}

// Excellent signal
if (data.rssi && data.rssi > -90 && data.snr && data.snr > 10) {
    alerts.push({
        type: 'info',
        severity: 'low',
        message: `Excellent pass from ${data.satellite}: RSSI ${data.rssi} dBm, SNR ${data.snr} dB`,
        timestamp: new Date().toISOString(),
        data: data
    });
}

if (alerts.length > 0) {
    msg.payload = alerts;
    return msg;
}

return null;

const alerts = msg.payload;

// Store in context
let alertHistory = flow.get('alert_history') || [];
alertHistory.unshift(...alerts);
if (alertHistory.length > 50) {
    alertHistory = alertHistory.slice(0, 50);
}
flow.set('alert_history', alertHistory);

// Emit to websocket
msg.payload = {
    type: 'alert',
    alerts: alerts
};

return msg;

const history = flow.get('packet_history') || [];
const stats = flow.get('statistics') || {};

msg.payload = {
    data: history,
    stats: stats,
    timestamp: new Date().toISOString()
};

msg.statusCode = 200;
return msg;

const stats = flow.get('statistics') || {};
const alerts = flow.get('alert_history') || [];

msg.payload = {
    statistics: stats,
    recentAlerts: alerts.slice(0, 10),
    timestamp: new Date().toISOString()
};

msg.statusCode = 200;
return msg;
